  // ==================================================
  // 19 - د عمومي درسونو اضافه کول
  // ==================================================

  // د PDF د مخونو نقشه: 2:1-5=2; 2:6-10=3; 3:1-4=4
  // که د سورت شمېره ورنه کړل شي، نقشه د ټاکلي سورت لپاره کار کوي.
  function parseQuranPageMap(raw) {
    return String(raw || '')
      .split(/[;،,\n]+/)
      .map(part => {
        const match = part.trim().match(/^(?:(\d+)\s*:\s*)?(\d+)\s*-\s*(\d+)\s*=\s*(\d+)$/);
        if (!match) return null;
        const surah = match[1] ? Number(match[1]) : null;
        const fromAyah = Number(match[2]);
        const toAyah = Number(match[3]);
        const page = Number(match[4]);
        if ((surah !== null && (surah < 1 || surah > 114)) || fromAyah < 1 || toAyah < fromAyah || page < 1) return null;
        return { surah, fromAyah, toAyah, page };
      })
      .filter(Boolean);
  }

  // د قرآن د آیتونو او د یوې ګډې آډیو د پیل وخت نقشه.
  // بېلګه: 2:15=16:20 یا 2:16=17:45؛ وخت د دقیقو:ثانیو په بڼه دی.
  function parseQuranAudioMap(raw) {
    const digitMap = { '۰':'0','۱':'1','۲':'2','۳':'3','۴':'4','۵':'5','۶':'6','۷':'7','۸':'8','۹':'9','٠':'0','١':'1','٢':'2','٣':'3','٤':'4','٥':'5','٦':'6','٧':'7','٨':'8','٩':'9' };
    return String(raw || '')
      .replace(/[۰-۹٠-٩]/g, digit => digitMap[digit] || digit)
      .split(/[;،,\n]+/)
      .map(part => {
        const match = part.trim().match(/^(\d+)\s*:\s*(\d+)\s*=\s*(?:(\d+):)?(\d{1,2})$/);
        if (!match) return null;
        const surah = Number(match[1]);
        const ayah = Number(match[2]);
        const minutes = match[3] == null ? 0 : Number(match[3]);
        const seconds = Number(match[4]);
        if (surah < 1 || surah > 114 || ayah < 1 || seconds > 59) return null;
        return { surah, ayah, startSeconds: minutes * 60 + seconds };
      })
      .filter(Boolean);
  }

  function findQuranAudioStart(item, ayahNumber, surahNumber) {
    const ayah = Number(ayahNumber);
    const surah = Number(surahNumber);
    if (!Number.isInteger(ayah) || ayah < 1 || !Number.isInteger(surah) || surah < 1) return null;
    const entry = (item?.audioMap || []).find(row => Number(row.surah) === surah && Number(row.ayah) === ayah);
    return entry ? Number(entry.startSeconds) * 1000 : null;
  }

  function findQuranPdfPage(item, ayahNumber, surahNumber) {
    const ayah = Number(ayahNumber);
    const surah = Number(surahNumber);
    if (!Number.isInteger(ayah) || ayah < 1) return null;
    const entry = (item?.pageMap || []).find(row => {
      const surahMatches = row.surah == null
        ? (!item?.surah || String(item.surah).trim() === String(surahNumber).trim())
        : Number(row.surah) === surah;
      return surahMatches && ayah >= Number(row.fromAyah) && ayah <= Number(row.toAyah);
    });
    return entry?.page || null;
  }

  async function openQuranPdfAtAyah(item, ayahNumber, surahNumber) {
    if (!item?.pdf) {
      Alert.alert('PDF نشته', 'د دې تفسیر یا کتاب PDF نه دی ثبت شوی.');
      return;
    }
    const page = findQuranPdfPage(item, ayahNumber, surahNumber);
    if (!page) {
      Alert.alert(
        'د مخ نقشه نشته',
        'د دې سورت او آیت لپاره د PDF مخ نه دی ثبت شوی. بشپړ کتاب لوستلی شئ؛ د دقیق مخ لپاره د اډمین له خوا د سورت، آیتونو او PDF مخ نقشه ثبت کړئ.'
      );
      await openPdf(item, 1);
      return;
    }
    await openPdf(item, page);
  }

  async function addGlobalItem() {
    const savedAsQuran = quranMode;
    const parsedPageMap = savedAsQuran ? parseQuranPageMap(formPageMap) : [];
    const enteredPageMapParts = String(formPageMap || '').split(/[;،,\n]+/).filter(part => part.trim());
    if (savedAsQuran && enteredPageMapParts.length && parsedPageMap.length !== enteredPageMapParts.length) {
      Alert.alert('د مخونو نقشه ناسمه ده', 'مهرباني وکړئ دا بڼه وکاروئ: 2:1-5=2; 2:6-10=3. لومړۍ شمېره سورت، منځنۍ د آیتونو حدود او وروستۍ شمېره د PDF مخ دی.');
      return;
    }
    const parsedAudioMap = savedAsQuran ? parseQuranAudioMap(formAudioMap) : [];
    const enteredAudioMapParts = String(formAudioMap || '').split(/[;،,\n]+/).filter(part => part.trim());
    if (savedAsQuran && enteredAudioMapParts.length && parsedAudioMap.length !== enteredAudioMapParts.length) {
      Alert.alert('د آډیو وختونو نقشه ناسمه ده', 'دا بڼه وکاروئ: 2:15=16:20; 2:16=17:45. لومړی سورت:آیت او بیا د آډیو د پیل وخت (دقیقې:ثانیې).');
      return;
    }
    if (!formTitle.trim()) {
      Alert.alert('خبرتیا', 'د درس نوم ولیکئ.');
      return;
    }

    const newItem = {
      id: Date.now().toString(),
      title: formTitle.trim(),
      description: formDescription,
      text: formText,
      audio: formAudio,
      pdf: formPDF,
      video: formVideo,
      scholar: formScholar.trim(),
      language: formLanguage,
      madhhab: formMadhhab.trim(),
      resourceCategory: formResourceType,
      source: formSource.trim(),
      permission: formPermission.trim(),
      section: quranMode ? 'قرآن کریم او علوم القرآن' : selectedSection,
      folder: quranMode ? 'قرآن کریم' : selectedFolder,
      level: formLevel,
      surah: quranMode ? formSurah.trim() : '',
      ayah: quranMode ? formAyah.trim() : '',
      pageMap: parsedPageMap,
      audioMap: parsedAudioMap,
      resourceType: quranMode ? 'quran' : formResourceType,
      createdAt: new Date().toISOString()
    };

    await saveGlobalItems([
      newItem,
      ...globalItems
    ]);

    clearForm();
    setScreen(savedAsQuran ? 'quran' : 'sectionFolder');
  }

