  function isValidClock(value) {
    return /^([01]?[0-9]|2[0-3]):[0-5][0-9]$/.test(String(value || '').trim());
  }

  // ==================================================
  // 23.6 - د بیان، ذکر او دعا تقسیم اوقات
  // ==================================================

  async function saveSchedulePlan() {
    if (!scheduleTitle.trim()) {
      Alert.alert('خبرتیا', 'د بیان، ذکر یا دعا نوم ولیکئ.');
      return;
    }
    if (!isValidClock(scheduleStartTime) || !isValidClock(scheduleEndTime)) {
      Alert.alert('ناسم وخت', 'د پیل او ختم وخت د 24 ساعته بڼې لکه 08:30 ولیکئ.');
      return;
    }
    const toMinutes = value => {
      const [h, m] = value.split(':').map(Number);
      return h * 60 + m;
    };
    if (toMinutes(scheduleEndTime) <= toMinutes(scheduleStartTime)) {
      Alert.alert('ناسم وخت', 'د ختم وخت باید د پیل له وخت څخه وروسته وي.');
      return;
    }
    if (scheduleDate.trim() && !/^\d{4}-\d{2}-\d{2}$/.test(scheduleDate.trim())) {
      Alert.alert('ناسمه نېټه', 'نېټه د YYYY-MM-DD په بڼه ولیکئ، یا یې تشه پرېږدئ چې هره ورځ تکرار شي.');
      return;
    }

    const extraTimes = scheduleExtraTimes
      .split(/[,،\n]+/)
      .map(value => value.trim())
      .filter(Boolean);
    const allTimes = [scheduleStartTime.trim(), scheduleEndTime.trim(), ...extraTimes];
    if (allTimes.some(value => !isValidClock(value))) {
      Alert.alert('ناسم وخت', 'د اضافي وختونو بېلګه: 09:00، 13:30، 20:00');
      return;
    }
    const uniqueTimes = [...new Set(allTimes)];
    if (scheduleDate.trim()) {
      const dateCheck = new Date(`${scheduleDate.trim()}T${scheduleStartTime.trim()}:00`);
      if (Number.isNaN(dateCheck.getTime()) || dateCheck <= new Date()) {
        Alert.alert('ناسمه نېټه', 'د راتلونکې نېټې او وخت معلومات ولیکئ.');
        return;
      }
    }
    if (settings.notificationsEnabled === false) {
      Alert.alert('خبرتیاوې بندې دي', 'د تقسیم اوقات د خبرتیاوو لپاره لومړی خبرتیاوې فعالې کړئ.');
      return;
    }
    const allowed = await requestNotificationPermission();
    if (!allowed) return;

    const scheduledIds = [];
    const scheduleId = `plan-${Date.now()}`;
    try {
      for (const clock of uniqueTimes) {
        const [hour, minute] = clock.split(':').map(Number);
        let trigger;
        if (scheduleDate.trim()) {
          const date = new Date(`${scheduleDate.trim()}T${clock}:00`);
          if (date <= new Date()) continue;
          trigger = {
            type: Notifications.SchedulableTriggerInputTypes.DATE,
            date
          };
        } else {
          trigger = {
            type: Notifications.SchedulableTriggerInputTypes.DAILY,
            hour,
            minute
          };
        }
        const isStart = clock === scheduleStartTime.trim();
        const isEnd = clock === scheduleEndTime.trim();
        const label = isStart ? 'د پیل وخت' : isEnd ? 'د ختم وخت' : 'د یادونې وخت';
        const notificationId = await Notifications.scheduleNotificationAsync({
          content: {
            title: `میراث اسلام – ${scheduleTitle.trim()}`,
            body: `${label}: ${scheduleKind} (${clock})`,
            sound: true,
            data: { scheduleId, kind: scheduleKind, clock }
          },
          trigger
        });
        scheduledIds.push(notificationId);
      }

      if (!scheduledIds.length) {
        throw new Error('No future notification time was scheduled.');
      }
      const plan = {
        id: scheduleId,
        type: 'schedulePlan',
        title: scheduleTitle.trim(),
        kind: scheduleKind,
        date: scheduleDate.trim() || 'هره ورځ',
        startTime: scheduleStartTime.trim(),
        endTime: scheduleEndTime.trim(),
        extraTimes: uniqueTimes.filter(time => time !== scheduleStartTime.trim() && time !== scheduleEndTime.trim()),
        text: scheduleText.trim(),
        audio: scheduleAudio || '',
        repeatDaily: !scheduleDate.trim(),
        notificationIds: scheduledIds,
        createdAt: new Date().toISOString()
      };
      await saveReminders([plan, ...reminders]);
      resetScheduleForm();
      setScreen('schedulePlanner');
      Alert.alert('بریالی شو', 'تقسیم اوقات ثبت شو او خبرتیاوې ورته تنظیم شوې.');
    } catch (error) {
      await Promise.all(scheduledIds.map(id => Notifications.cancelScheduledNotificationAsync(id).catch(() => null)));
      Alert.alert('ستونزه', 'تقسیم اوقات ثبت نه شو. د خبرتیاوو اجازه او وختونه بیا وګورئ.');
    }
  }

  async function deleteSchedulePlan(id) {
    const plan = reminders.find(item => item.id === id);
    try {
      const ids = plan?.notificationIds || (plan?.notificationId ? [plan.notificationId] : []);
      await Promise.all(ids.map(notificationId => Notifications.cancelScheduledNotificationAsync(notificationId).catch(() => null)));
      await saveReminders(reminders.filter(item => item.id !== id));
    } catch (error) {
      Alert.alert('ستونزه', 'تقسیم اوقات حذف نه شو.');
    }
  }

