  async function addReminder() {
    if (settings.notificationsEnabled === false) {
      Alert.alert('خبرتیاوې بندې دي', 'لومړی د تنظیماتو له برخې خبرتیاوې فعالې کړئ.');
      return;
    }
    if (
      !formTitle.trim() ||
      !formDate.trim() ||
      !formTime.trim()
    ) {
      Alert.alert(
        'خبرتیا',
        'د خبرتیا نوم، نېټه او وخت ولیکئ.'
      );
      return;
    }

    const allowed =
      await requestNotificationPermission();

    if (!allowed) return;

    const dateTime = new Date(
      `${formDate}T${formTime}:00`
    );

    if (
      Number.isNaN(dateTime.getTime()) ||
      dateTime <= new Date()
    ) {
      Alert.alert(
        'ناسم وخت',
        'راتلونکې نېټه او سم وخت ولیکئ.'
      );
      return;
    }

    try {
      const notificationId =
        await Notifications.scheduleNotificationAsync({
          content: {
            title: 'میراث اسلام',
            body: formTitle,
            sound: true
          },
          trigger: {
            type: Notifications.SchedulableTriggerInputTypes.DATE,
            date: dateTime
          }
        });

      const newReminder = {
        id: Date.now().toString(),
        title: formTitle,
        date: formDate,
        time: formTime,
        notificationId
      };

      await saveReminders([
        newReminder,
        ...reminders
      ]);

      clearForm();
      setScreen('reminders');

      Alert.alert('بریالی شو', 'خبرتیا ثبت شوه.');

    } catch (error) {
      Alert.alert('ستونزه', 'خبرتیا ثبت نه شوه.');
    }
  }

  async function deleteReminder(id) {
    const reminder = reminders.find(
      item => item.id === id
    );

    try {
      const notificationIds = reminder?.notificationIds || (reminder?.notificationId ? [reminder.notificationId] : []);
      await Promise.all(notificationIds.map(notificationId =>
        Notifications.cancelScheduledNotificationAsync(notificationId).catch(() => null)
      ));

      await saveReminders(
        reminders.filter(item => item.id !== id)
      );

    } catch (error) {
      Alert.alert('ستونزه', 'خبرتیا حذف نه شوه.');
    }
  }

