  // د ګډې آډیو لپاره د پیل وخت په mm:ss یا hh:mm:ss بڼه ثانیو ته اړوي.
  function parseMediaStartTime(value) {
    const raw = String(value || '').trim().replace(/[۰-۹٠-٩]/g, digit => ({'۰':'0','۱':'1','۲':'2','۳':'3','۴':'4','۵':'5','۶':'6','۷':'7','۸':'8','۹':'9','٠':'0','١':'1','٢':'2','٣':'3','٤':'4','٥':'5','٦':'6','٧':'7','٨':'8','٩':'9'}[digit] || digit));
    if (!raw) return 0;
    const parts = raw.split(':').map(Number);
    if (parts.length < 2 || parts.length > 3 || parts.some(n => !Number.isInteger(n) || n < 0)) return null;
    if (parts[parts.length - 1] > 59 || (parts.length === 3 && parts[1] > 59)) return null;
    return parts.length === 2 ? parts[0] * 60 + parts[1] : parts[0] * 3600 + parts[1] * 60 + parts[2];
  }

