  function getQuranResults() {
    const digitMap = { '۰':'0','۱':'1','۲':'2','۳':'3','۴':'4','۵':'5','۶':'6','۷':'7','۸':'8','۹':'9','٠':'0','١':'1','٢':'2','٣':'3','٤':'4','٥':'5','٦':'6','٧':'7','٨':'8','٩':'9' };
    const query = quranSearch.trim().toLowerCase().replace(/[۰-۹٠-٩]/g, digit => digitMap[digit] || digit);
    const items = globalItems.filter(item => item.resourceType === 'quran');
    if (!query) return items;
    const numeric = query.match(/^(\d+)\s*[:،-]\s*(\d+)$/);
    return items.filter(item => {
      const text = `${item.title || ''} ${item.description || ''} ${item.surah || ''} ${item.ayah || ''} ${item.scholar || ''} ${item.text || ''} ${item.source || ''} ${item.language || ''} ${item.resourceCategory || ''}`.toLowerCase();
      if (numeric) {
        const surahMatches = String(item.surah || '').trim() === numeric[1] || String(item.surahName || '').toLowerCase() === numeric[1] || (item.pageMap || []).some(row => Number(row.surah) === Number(numeric[1]));
        const ayahRange = String(item.ayah || '').match(/^(\d+)\s*-\s*(\d+)$/);
        const ayahMatches = String(item.ayah).trim() === numeric[2] || (ayahRange && Number(numeric[2]) >= Number(ayahRange[1]) && Number(numeric[2]) <= Number(ayahRange[2])) || (item.pageMap || []).some(row => (row.surah == null || Number(row.surah) === Number(numeric[1])) && Number(numeric[2]) >= Number(row.fromAyah) && Number(numeric[2]) <= Number(row.toAyah));
        return surahMatches && ayahMatches;
      }
      return text.includes(query);
    });
  }

